-- AVES Saha R15D-rc3.9.4
-- Kütüphane senkron raporu: yerel data/madde_kutuphanesi.json ile canlı
-- Supabase madde_kutuphanesi tablosu arasında 891 alan farkı bulundu (bkz.
-- kullanıcıya sunulan 'Kütüphane Senkron Raporu' denetim artifact'i). Kullanıcı
-- onayıyla EKLEMELİ bir strateji uygulandı: hiçbir tarafın mevcut içeriği
-- silinmedi/üzerine yazılmadı, yalnız boşluklar dolduruldu ve az sayıdaki
-- gerçek çakışmada (ikisi de dolu, farklı) daha eksiksiz olan taraf seçildi.
--
-- 1) 5 gerçek çakışma (conflict): dev (dosya) daha eksiksiz/doğruydu, canlı
--    bilinçli olarak üzerine yazıldı. MAD-1007 (KAP-03) tersine, canlı daha
--    eksiksizdi; bu satır dosyaya çekildi (ayrı script, DB migration gerekmez).
-- 2) 531 'yalnız dosyada var' alan: canlıda BOŞ olan denetci_yonlendirmesi/
--    olcu1_adi/aranmaz_kosulu/resmi_madde_metni alanları dosyadan dolduruldu.
--    'Ölçülen değer' gibi jenerik/işlevsiz olcu1_adi yer tutucuları (255 satır)
--    kasıtlı olarak dışarıda bırakıldı (app.js belirsizEtiket() kontrolü zaten
--    bunları görünmez sayıyor, boş bırakmakla aynı davranış).
-- 3) 104 'yalnız canlıda var' alan (olcu1_birimi, olcum_tanimlari, aranmaz_kosulu,
--    1 tam satır MAD-1010/KAP-06) yalnız dosyaya çekildi; canlıda zaten
--    doğruydu, DB migration gerekmedi.
--
-- Veri silmez; başlamış denetimlerin saha_kontrol snapshot satırlarına dokunmaz.

begin;

-- 1) Çakışmalarda dosyanın (daha eksiksiz) değeri kazandı.
update public.madde_kutuphanesi set aranmaz_kosulu = 'Kabin eteği veya düşey sürgülü kapı parçası bu istisna bölgesinde değilse Aranmaz.' where madde_id = 'MAD-0080';
update public.madde_kutuphanesi set denetci_yonlendirmesi = 'Karşı ağırlık veya dengeleme ağırlığı kullanılmışsa bunun kabinle aynı kuyu içinde bulunduğunu doğrulayın. Bu bileşen yoksa maddeyi Aranmaz olarak değerlendirin.' where madde_id = 'MAD-0200';
update public.madde_kutuphanesi set denetci_yonlendirmesi = 'Kontrol: Çatlak, deformasyon, gevşeme ve zayıf taşıyıcı bağlantıları incele.' where madde_id = 'MAD-0263';
update public.madde_kutuphanesi set resmi_madde_metni = 'Yalıtım direnci, gerilim taşıyan her iletken ile toprak arasında ölçülmelidir. Geçerli devre için >0,5 MΩ (test voltajı 500 V); güvenlik ekipmanları için >0,5 MΩ (test voltajı 500 V).' where madde_id = 'MAD-0548';
update public.madde_kutuphanesi set denetci_yonlendirmesi = 'Makara dairesi bulunuyorsa erişim kapısının net yüksekliği en az 1400 mm, net genişliği en az 600 mm olmalıdır. Makara dairesi yoksa Aranmaz olarak değerlendirin.' where madde_id = 'MAD-0635';

-- 2) 'Yalnız dosyada var' alanlar: yalnız canlıda BOŞ olanlar dolduruldu.
create temporary table r15d_rc394_sync_aranmaz_kosulu (madde_id text primary key, yeni_deger text not null) on commit drop;

do $$
declare v_count integer;
begin
  select count(*) into v_count from r15d_rc394_sync_aranmaz_kosulu;
  if v_count <> 1 then raise exception 'Beklenen 1 satir yerine % tanesi listelendi', v_count; end if;
end $$;

update public.madde_kutuphanesi m
set aranmaz_kosulu = e.yeni_deger
from r15d_rc394_sync_aranmaz_kosulu e
where m.madde_id = e.madde_id
  and coalesce(m.aranmaz_kosulu, '') = '';

create temporary table r15d_rc394_sync_olcu1_adi (madde_id text primary key, yeni_deger text not null) on commit drop;

do $$
declare v_count integer;
begin
  select count(*) into v_count from r15d_rc394_sync_olcu1_adi;
  if v_count <> 17 then raise exception 'Beklenen 17 satir yerine % tanesi listelendi', v_count; end if;
end $$;

update public.madde_kutuphanesi m
set olcu1_adi = e.yeni_deger
from r15d_rc394_sync_olcu1_adi e
where m.madde_id = e.madde_id
  and coalesce(m.olcu1_adi, '') = '';

create temporary table r15d_rc394_sync_denetci_yonlendirmesi (madde_id text primary key, yeni_deger text not null) on commit drop;

do $$
declare v_count integer;
begin
  select count(*) into v_count from r15d_rc394_sync_denetci_yonlendirmesi;
  if v_count <> 512 then raise exception 'Beklenen 512 satir yerine % tanesi listelendi', v_count; end if;
end $$;

update public.madde_kutuphanesi m
set denetci_yonlendirmesi = e.yeni_deger
from r15d_rc394_sync_denetci_yonlendirmesi e
where m.madde_id = e.madde_id
  and coalesce(m.denetci_yonlendirmesi, '') = '';

create temporary table r15d_rc394_sync_resmi_madde_metni (madde_id text primary key, yeni_deger text not null) on commit drop;

do $$
declare v_count integer;
begin
  select count(*) into v_count from r15d_rc394_sync_resmi_madde_metni;
  if v_count <> 1 then raise exception 'Beklenen 1 satir yerine % tanesi listelendi', v_count; end if;
end $$;

update public.madde_kutuphanesi m
set resmi_madde_metni = e.yeni_deger
from r15d_rc394_sync_resmi_madde_metni e
where m.madde_id = e.madde_id
  and coalesce(m.resmi_madde_metni, '') = '';

update public.kutuphane_bolum_surumleri set surum = surum + 1, updated_at = now();

commit;

-- Salt okunur doğrulama.
select madde_id, aranmaz_kosulu, denetci_yonlendirmesi, resmi_madde_metni
from public.madde_kutuphanesi
where madde_id in ('MAD-0080','MAD-0200','MAD-0263','MAD-0548','MAD-0635')
order by madde_id;

select count(*) as aktif_madde_bos_rehber
from public.madde_kutuphanesi
where aktif is true and coalesce(denetci_yonlendirmesi,'') = '';