insert into r15d_rc394_sync_denetci_yonlendirmesi (madde_id, yeni_deger) values
  ('MAD-0112', 'Bir sığınma boşluğundan yatay olarak 0,30 m içinde çalıştırılabilen kumanda aygıtı bulunmalıdır.'),
  ('MAD-0113', 'Kontrol veya bakım personeli için giriş noktasından 1m''den daha fazla olmayan , kolayca erişilebilir,iki konumda kararlı ve yanlışlıkla çalışmaya karşı korunmuş bir durdurma aygıtı bulunmalıdır. Bu aygıt, erişim noktasından 1m''den daha uzağa yerleştirilmemişse, kontrol çalışması kumandasının yanında bulunan aygıt olabilir.'),
  ('MAD-0114', 'Kabin üstü durdurma anahtarının üstünde veya yakınında, “DUR/STOP” kelimesi olmalıdır.'),
  ('MAD-0115', 'Topraklı priz çıkışı bulunmalıdır.'),
  ('MAD-0116', 'Muayene kumanda istasyonu özellikleri; Elektrik güvenlik aygıtları için gereklilikleri sağlayan bir anahtar (kontrol çalışma anahtarı). İki konumlu olması gereken bu anahtar, yanlışlıkla çalıştırılmaya karşı korunmuş olmalıdır.'),
  ('MAD-0117', 'Kontrol çalışma anahtarı üzerinde veya yanında “NORMAL” ve “KONTROL” kelimeleri olmalıdır.'),
  ('MAD-0118', 'Açıkça gösterilen yön yardımıyla kazara çalışmaya karşı korunmuş “YUKARI” yönlü basma butonu ( Buton rengi beyaz üstü siyah ) ve “AŞAĞI” yönlü basma butonu (Buton rengi siyah üstü beyaz) (IEC 60417:2002,5022) olmalıdır. (Çizelge 17 )'),
  ('MAD-0119', 'Kazara çalışmaya karşı korunmuş “ÇALIŞTIR" basma butonu (Buton rengi mavi üstü beyaz) (IEC 60417:2002,5023) olmalıdır. (Çizelge 17 )'),
  ('MAD-0120', 'Kontrol kumanda istasyonu, asgari IPXXD'' nin (EN 60529) koruma derecesine sahip olmalıdır.(1 mm çapında tel ile içerisine ulaşılamaz.)'),
  ('MAD-0121', 'Birden fazla kontrol kumanda istasyonu, “KONTROL”e geçmiş ise, kontrol kumanda istasyonunda aynı basma butonları aynı anda basılmadıkça, bunların herhangi birinden kabini hareket ettirmek mümkün olmamalıdır.'),
  ('MAD-0122', 'Kabin üstü bakım kumandası devreye alındığında, otomatik kapıların kumandaları dahil, normal kumandalar, elektrikli elle kumanda ve varsa yükleme rampası hareketi kumandası devre dışı kalmalıdır.'),
  ('MAD-0123', 'Bakım kumandası devrede iken , normal kabin seyir sınırları aşılmamalıdır, yani normal çalışmada durma konumları aşılmamalıdır.'),
  ('MAD-0124', 'Bakım kumandası devrede iken ,asansörün çalışması güvenlik aygıtlarına bağlı kalmalıdır.'),
  ('MAD-0125', 'Kontrol konumunda kontrol çalışma anahtarı, kabin hızı 0,63 m/s''yi aşmamalıdır.'),
  ('MAD-0126', 'Kontrol konumunda kontrol çalışma anahtarı, kabin üstü üzerindeki herhangi bir ayakta durma alanındaki düşey yükseklik mesafesi 2,0 m veya daha az iken, kabin hızı 0,30 m/s''yi aşmamalıdır.'),
  ('MAD-0127', 'Mahsur kalma tehlikesi varsa ve bu mahsur kalma durumu için hiçbir vasıta sağlanmamışsa EN 81-28''e göre sığınma alanından kullanılabilecek alarm başlatma cihazları bulunmalıdır.'),
  ('MAD-0128', 'Kabin üstü, azami insan sayısını taşıyacak şekilde yeterli dayanıma sahip olmalıdır. Ancak kabin üstü, kalıcı deformasyon geçirmeksizin, 0,30 m x 0,30 m''lik bir alan üzerinde herhangi bir konumda asgari 2000 N''luk bir kuvvete dayanabilmelidir.'),
  ('MAD-0129', 'Kabin üstünün, bir kişinin çalışması veya çalışma alanları arasında hareket etmesi gereken yüzeyi, kaymaz özellikte olmalıdır.'),
  ('MAD-0131', 'Kabinin kuyu içindeki seyri boyunca herhangi bir konumunda, tüm kapılar kapalı olduğunda bile, aşağıdaki aydınlatma yoğunluğunu sağlayan, kalıcı olarak kurulmuş elektrikli aydınlatma ile donatılmalıdır: a) düşey izdüşümü içinde kabin üstünün 1,0 m üzerinde en az 50 lüks; b) kabin veya aksamın oluşturduğu gölgelerin haricinde, a)''da tanımlanan yerlerin dışında enaz 20 lüks. Lüks seviyesi okumaları alınırken, ışıkölçer en güçlü ışık kaynağına doğru yöneltilmelidir.'),
  ('MAD-0132', 'Kabin üstü, aşağıda verilenlerden birine uygun asgari 0,10 m yüksekliğe konumlandırılmış korkuluk eteği ile donatılmalıdır: 1) kabin üstünün dış kenarı üzerinde, veya 2) bir korkuluk bulunduğunda, dış kenar ile korkuluğun konumu arasında.'),
  ('MAD-0133', 'Kabin üstünün dış kenarının ötesinde ve onun dikine olarak asansör kuyusunun duvarına olan yatay düzlemdeki serbest mesafe 0,30 m''yi aştığı yerlerde, verilen boyutlarda bir korkuluk sağlanmalıdır.'),
  ('MAD-0134', 'Kabin üstünün dış kenarı ile kuyu duvarı arasındaki mesafesinin 0,30 m''den fazla olduğu yerlerde, kabin üstünün dış kenarı ile ilgili aksamın arasına veya korkuluğun ucu ile aksamın arasına 0,30 m''den daha büyük çaplı yatay bir daire yerleştirmek mümkün olmamalıdır.'),
  ('MAD-0135', 'Korkuluklar, korkulukların yarı yüksekliğinde bir ara çubuk ve bir el tutamağından oluşmalıdırlar.'),
  ('MAD-0136', 'Korkuluğun el tutamağının iç kenarı ile kuyu duvarının ötesindeki yatay düzlemdeki serbest mesafe düşünüldüğünde yüksekliği en az aşağıdaki gibi olmalıdır: 1) mesafenin 0,50 m''ye kadar olduğu yerlerde 0,70 m, 2) mesafenin 0,50 m''yi aştığı yerlerde 1,10m.'),
  ('MAD-0137', 'Korkuluk, kabin üstünün kenarlarından en fazla 0,15 m mesafede yerleştirilmelidir.'),
  ('MAD-0138', 'El tutamağının dış kenarı ile kuyu duvarındaki herhangi bir parça (karşı ağırlık veya dengeleme ağırlığı, anahtarlar, raylar, konsollar, vb.) arasındaki yatay mesafe en az 0,10 m olmalıdır.'),
  ('MAD-0139', 'Korkuluğun üstünde herhangi bir noktaya dik açılarda yatay olarak 1000N''luk bir kuvvet uygulandığında, korkuluk 50 mm''nin üzerinde bir elastik deformasyon göstermeden bu kuvvete dayanmalıdır.'),
  ('MAD-0140', 'Kabin üstü korkuluk üzerinde uyarı levhası veya yazısı olmalıdır.'),
  ('MAD-0143', 'Kontrol ve bakım çalışmaları için kabin üstünde birden fazla kişinin bulunması gerekliyse, her ilave kişi için ek bir sığınma boşluğu sağlanmalıdır. Birden fazla sığınma boşluğu bulunması durumunda, bunlar aynı tipte olmalı ve birbirine karışmamalıdır.'),
  ('MAD-0145', 'Bu sığınma boşluğu sağlanmıyor ise riskin önlenmesi için farklı uygulanabilir yöntemler uygulanmalıdır. (bkz. TS EN 12100 ve TS EN ISO 14798)'),
  ('MAD-0146', 'Kabin üstü veya kabin üstündeki donanım üzerindeki, asgari 0,12 m2 net alana ve asgari boyutu 0,25 m''den büyük olan en küçük kenara sahip herhangi bir sürekli alan, bir kişinin durabildiği bir yer olarak kabul edilir. Kabin, en yüksek konumunda olduğunda, bu tür bir alanın üzeri ile kuyu tavanının en alt kısımları (kirişler ve tavanın altında bulunan kısımlar dâhil) arasındaki düşey açıklık, ilgili sığınma boşluğu/boşlukları yüksekliğinde olmalıdır. 0,035 v² değerinin dikkate alınmasına gereklidir.'),
  ('MAD-0147', 'Kabin/karşı ağırlık en yüksek konumunda, kılavuz rayların uzunluğu, en az 0,10 m ilave kılavuzlanmış hareket seyri sağlayacak şekilde olmalıdır. 0,035 v² değerinin dikkate alınmasına gereklidir.'),
  ('MAD-0148', 'Kabin, en yüksek konumundayken kabin üstüne sabitlenmiş donanımın en yüksek kısımları, kabinin izdüşümü içinde herhangi bir düşey veya eğimli yönde en az 0,50 m olmalıdır. 0,035 v² değerinin dikkate alınmasına gereklidir.'),
  ('MAD-0149', 'Kabin, en yüksek konumundayken kılavuz patenlerinin veya makaralarının, halat bağlantı uçlarının ve varsa düşey sürgülü kapıların üst tertibatlarının veya parçalarının en üst kısmı, kabinin izdüşümü içinde 0,40 m''lik bir yatay mesafe içinde herhangi bir düşey yönde en az 0,10 m olmalıdır. 0,035 v² değerinin dikkate alınmasına gereklidir.'),
  ('MAD-0150', 'Kabin, en yüksek konumundayken korkuluğun en yüksek kısmı en az aşağıda verildiği gibi olmalıdır: 1) kabinin izdüşümü içinde 0,40 m''lik ve korkuluğun dışında 0,10 m''lik yatay bir mesafe içinde 0,30m; 2) kabinin izdüşümü içinde 0,40 m''nin ilerisinde herhangi bir eğimli mesafede 0,50 m. 0,035 v² değerinin dikkate alınmasına gereklidir.'),
  ('MAD-0151', 'Kuyu alanının 0,025 katı kadar ve en az 0,1 m2 olmak üzere kuyu havalandırması sağlanmalıdır.'),
  ('MAD-0152', 'Güvenlik tertibatı aşağı yönde çalışabilir olmalı ve anma yükünü taşıyan bir kabini veya bir karşı ağırlığı veya dengeleme ağırlığını, hız regülatörünün devreye girme hızında veya eğer askı aygıtları koparsa, kılavuz rayları kavrayarak durdurabilecek ve kabini, karşı ağırlığı veya dengeleme ağırlığını orada tutacak özellikte olmalıdır.'),
  ('MAD-0153', 'Güvenlik tertibatı üzerine aşağıda belirtilen bilgileri içeren bir plaka sabitlenmelidir: a) güvenlik tertibatının imalatçısının ismi; b) tip inceleme belgesi numarası; c) güvenlik tertibatının tipi; d) eğer ayarlanabilir ise, güvenlik tertibatı izin verilen yük aralığı ile veya kullanma talimatında yük aralığı ile olan ilişki belirtilmişse ayar parametresi ile işaretlenmelidir.'),
  ('MAD-0154', 'Kabin güvenlik tertibatı (kaymalı tip veya beyan hızı 0,63 m/s'' yi aşmıyorsa anlık tip) olmalıdır.'),
  ('MAD-0155', 'Eğer kabin veya karşı ağırlık veya dengeleme ağırlığı birkaç güvenlik tertibatı taşıyorsa, bunların hepsi kademeli tip olmalıdır.'),
  ('MAD-0156', 'Karşı ağırlığın veya dengeleme ağırlığının güvenlik tertibatı, eğer anma hızı 1 m/s''yi aşıyorsa kademeli tip olmalıdır, aksi hâlde güvenlik tertibatı ani etkili tip olabilir.'),
  ('MAD-0157', 'Kabin güvenlik tertibatı devreye girdiğinde, kabin üzerine monte edilmiş bir elektrik güvenlik aygıtı, güvenlik tertibatının çalışmasından önce veya o esnada makinenin durdurulmasını başlatmalıdır.'),
  ('MAD-0158', 'Halatların anma çapı en az 8 mm olmalıdır. **Makine modeli gereği 8 mm den düşük çapta halat kullanılacaksa test sertifikası sunulacaktır'),
  ('MAD-0159', 'Asgari halat veya zincir sayısı iki olmalıdır. İki halat veya zincir kullanılması durumunda birinin diğerine oranla uzaması bir elektrikli güvenlik tertibatı yardımıyla kontrol edilmelidir.'),
  ('MAD-0160', 'Halatların ucu kabine, karşı ağırlığa veya dengeleme ağırlığına, ya da halat donanımının ölü parçalarının askı noktalarına, soket tipi (geçmeli) kendinden sıkı geçmeli vasıtalarla (örneğin,EN 13411-6 veya EN 13411-7''ye göre), yüksükle emniyete alınmış gözlerle (örneğin, EN 13411-3''e göre) veya dövme bağlantı tespit uçlarıyla (örneğin EN 13411-8''e göre) sabitlenmelidir. Halat şişesi üstünde bilgileri olmalıdır. 1- Asimetrik Kamalı Soket (TS-EN 13411-6 ) =X ölçüsü, soket gövdesinin en yakın parçası ile klemens arasındaki mesafe, X oldukça küçükse halatın şekil bozukluğuna uğramasını önlemek için ve eğer halat gevşek ve X oldukça büyükse kamanın soket gövdesinden çıkmasını önlemek için kamanın toplam uzunluğunun % 75''inden daha fazla olmamalıdır. 2- Simetrik Kamalı Soket (TS-EN 13411-7 ) Soket gövdesinin en yakın parçasından klemens mesafesi, (Şekil B.1, X mesafesi,) halatın deformasyona uğramasını önlemek için (mesafe oldukça küçükse) veya kamanın soket gövdesinden çıkmasını önlemek için (halat gevşek ve X oldukça büyükse) kamanın boydan boya uzunluğunun % 40''ından daha fazla olmamalıdır.'),
  ('MAD-0161', 'Askı halatlarının veya zincirlerinin, en azından uçlarından birinde gerilimi eşitlemek için otomatik bir aygıt bulunmalıdır. (yay veya esnek eleman olmalıdır.)'),
  ('MAD-0162', 'Halatların tamburlara sabitlenmesi, kamalı klemensler ile engelleyici bir sistem kullanılarak veya en az iki adet klemens kullanılarak gerçekleştirilmelidir. Halat bağlantılarında kontra somun ve gupilya olmalıdır.'),
  ('MAD-0163', 'Elektrikli güvenlik tertibatı, kilitleme elemanları en az 7 mm bağlanmadıkça etkin olmamalıdır.'),
  ('MAD-0164', 'Kilitleme tertibatı üzerinde bilgi plakası olmalıdır. a) kilitleme aygıtının imalatçısının adı; b) tip inceleme belgesi numarası; c) kilitleme aygıtının tipi.'),
  ('MAD-0165', 'Karşı ağırlık bloklarının yerinden çıkması önlenmeli (çerçeve içinde güvenli hale gelmeli)'),
  ('MAD-0166', 'Karşı ağırlığına monte edilmiş saptırma kasnakları varsa koruma tertibatına sahip olmalı, Halatın makaralardan çıkması, halat ve makara arasına cisimlerin girmesi)'),
  ('MAD-0167', 'Kabin, karşı ağırlık veya dengeleme ağırlığının her biri, en az iki rijit çelik kılavuz raylar tarafından kılavuzlanmalıdır.'),
  ('MAD-0169', 'Kılavuz rayların konsollarına ve binaya sabitlendikleri bağlantılar, binanın normal oturması veya betonun çekmesinden kaynaklanan etkilerin ya otomatik olarak ya da basit bir ayarlama ile telafi edilmesine izin vermelidir. Bağlantı parçalarının, kılavuz rayların yerinden kurtulmasına yol açabilecek şekilde dönmesi önlenmelidir.'),
  ('MAD-0170', 'Kılavuz raylar, rayların bağlantıları ve bağlantı elemanları, asansörün güvenli çalışmasının sağlanması için üzerlerine uygulanan yüklere ve kuvvetlere dayanabilmelidir. Asansörün güvenli çalışmasının kılavuz raylarla ilgili hususları şunlardır: a) kabinin, karşı ağırlık veya dengeleme ağırlığının kılavuzlanması sağlanmalıdır; b) sehimler, aşağıdakiler yaşanmayacak şekilde sınırlandırılmalıdır: 1) kapıların kilidi istemsiz şekilde açılmamalı; 2) güvenlik aygıtlarının çalışması etkilenmemeli ve 3) hareketli parçalar diğer parçalarla çarpışmamalıdır.'),
  ('MAD-0171', 'Kat kapılarında paralel bağlı, pabuçlu topraklama hattı olmalıdır. Topraklamanın sürekliliği (kablo renkleri yeşil-sarı)'),
  ('MAD-0172', 'Cam paneller lamine olmalı, her iki tarafında (iç ve dış) herhangi bir noktadaki 30x30 cm alan üzerinde yatay statik 1000 N kuvvete kalıcı şekil bozukluğu olmaksızın dayanmalı'),
  ('MAD-0173', 'Cam paneller varsa, (Tedarikçinin ismi/ticari markası, tipi ve kalınlık) etiketine sahip olmalı'),
  ('MAD-0174', 'Kabine normal girişi sağlayan kuyudaki açıklıklar durak kapıları ile donatılmalı ve kabine giriş, bir kabin kapısıyla olmalıdır. Kapılar deliksiz olmalıdır.'),
  ('MAD-0175', 'Durak ve kabin kapıları kapatılmış iken, gerekli açıklıklar hariç, durak ve kabin girişlerini tamamen kapatmalıdır.'),
  ('MAD-0176', 'Yatay sürgülü durak ve kabin kapıları, kapı paneline sabitlenmiş olan kılavuz elemanın çalışmaması durumunda, kapı panelini/panellerini gereken konumda tutmak için aygıt ile donatılmalıdır.'),
  ('MAD-0177', 'Asansör çalışması, seviyeleme ve ön çalışma hariç kabin kapısı kilitlenmesine bağlı olmalı'),
  ('MAD-0178', 'Durak kapısının kapanmasının sağlanması için elektrikli güvenlik tertibatıyla donatılmalı'),
  ('MAD-0180', 'Kabin kilit açılma bölgesi dışında ise durak kapısı açıldığında, bir tertibat kapının kapanmasını ve kilitlenmesini sağlamalı (Durak kapısı kabin kapısı ile tahrik ediliyorsa)'),
  ('MAD-0181', 'Durak kapılarının kilit açma bölgesinin dışında kapalı olması (mekanik ve elektriksel)'),
  ('MAD-0182', 'Kilit açma bölgesi dışında 100 mm aralıkla durak kapısının serbest bırakılması ile kapı kapanmalı ve kilitlenmelidir'),
  ('MAD-0183', 'Kabin kapısının kılavuz kenarı ile durak kapıları arasında kuyuya erişimi sağlayan yatay mesafe, 0,12 m''yi aşmamalı,'),
  ('MAD-0185', 'Durak kapısı yayları kılavuzlanmış ve sıkıştırma ile çalışan tipten olmalı, kilidin açık olduğu anda yayların sarımları sıkışmış durumda olmamalı (birbirine değmemelidir)'),
  ('MAD-0188', 'Seviyeleme, ön çalışma ve bypas durumlar hariç, durak kapısının açık olması durumunda, asansörü hareket ettirmek veya hareket halinde tutmak mümkün olmamalı'),
  ('MAD-0189', 'Seviyeleme, ön çalışma ve bypas durumlar hariç, durak kapısının kilitlenmesi, kabinin hareketinden önce olmalı. Kilitlenme, bir elektrikli güvenlik tertibatı ile sağlanmalı'),
  ('MAD-0190', 'Kapının açılma yönünde uygulanan 300N''luk bir kuvvet kilitlenme etkisini azaltmamalı'),
  ('MAD-0191', 'Asansör kilit açılma bölgesinde durursa, 300N''dan daha az bir kuvvetle kabin içinden veya duraktan (üçgen anahtar ile), el ile kabin ve durak kapısını açmak mümkün olmalıdır.'),
  ('MAD-0192', 'Kabin hareket ettiğinde, kabin içinden kapının açılması 50N''dan büyük bir kuvvetle olmalıdır.'),
  ('MAD-0193', 'Kabin kilit açma bölgesi dışında iken, kabin kapısını 1000 N bir kuvvet ile 50mm den daha fazla açmak mümkün olmamalı ve otomatik bir güç çalışması altında kapı açılmamalıdır.'),
  ('MAD-0194', 'Tamamen kapalı kuyular deliksiz duvarlar, zemin ve tavan ile tamamen kapatılmış olmalıdır.'),
  ('MAD-0195', 'Kuyu iç yüzeyi ile kabin eşiği veya kabin kapısının çerçevesi veya sürgülü kapılarda kapanan kenar arasındaki yatay açıklık, kuyunun tam boyu 0,15 m''yi aşmamalı (0,5 m''yi aşmayan bir yükseklikte 0,2 m''ye kadar uzatılabilir, iki ardışık durak kapısı arasında bu tür girintiler birden fazla olmamalı)'),
  ('MAD-0196', 'Bir kabin üst korkuluğu ile erişim engellenmediği sürece, bir duvardan kuyuya herhangi bir yatay çıkıntı veya ayırıcı kirişler dâhil, 0,15 m''den daha büyük olan yatay kiriş üzerinde bir kişinin ayakta durması engellenmelidir. Koruma tedbirleri aşağıdaki şekillerde olmalıdır: a) 0,15 m''den daha büyük olan çıkıntılar, yatayla en az 45° açı yapacak şekilde pahlanmalıdır veya b) yatayla asgari 45° eğimli bir yüzey oluşturan bir saptırıcı, herhangi bir noktasına dik açıyla uygulanan, dairesel veya kare kesitli 5 cm2lik bir yüzeye eşit olarak dağıtılmış 300 N''luk bir kuvvete,kalıcı bir deformasyon olmadan,15 mm''den daha büyük elastik deformasyon olmadan dayanabilmelidir.'),
  ('MAD-0197', 'Durak kapısı etek sacı (kilit açma bölgesinin en az yarısı+5cm uzunluk, giriş genişliği+en az 2,5cm her taraftan genişlik, en az 60° açı yapan sert pah, pahın izdüşümü en az 2cm)'),
  ('MAD-0198', 'Bu yüzey metal levha gibi düzgün/sert malzemeden olmalı ve herhangi bir noktasında dikey olarak 5 cm²''lik yuvarlak/kare bir alana 300 N uygulandığında, kalıcı bir şekil değişikliği ve 15mm''den fazla elastik şekil değişikliği olmaksızın dayanabilmeli'),
